import itertools, random
from pqattest import MerkleSigner, multiproof_encode, multiproof_partition, multiproof_select
from pqattest.merkle import _multiproof_parse

def counter_tokens(start=0):
    state = {"value": start}
    def token_bytes(size):
        state["value"] += 1
        return state["value"].to_bytes(8, "big").rjust(size, b"\x00")
    return token_bytes

def brute_case(messages, proof, pk, leaves, budget):
    n = len(leaves)
    # precompute every fragment once
    frag = {}
    for a in range(n):
        for b in range(a+1, n+1):
            idx = tuple(leaves[i][0] for i in range(a, b))
            frag[(a,b)] = multiproof_select(messages, proof, public_key=pk, indices=idx)
    best = None
    for cuts in range(1, n+1):
        for bounds in itertools.combinations(range(1, n), cuts-1):
            bounds = (0,) + bounds + (n,)
            total = 0
            ends = ()
            for a, b in zip(bounds, bounds[1:]):
                p = frag[(a,b)]
                if len(p) > budget:
                    break
                total += len(p)
                ends += (leaves[b-1][0],)
            else:
                cand = (cuts, total, ends, bounds)
                if best is None or cand[:3] < best[:3]:
                    best = cand
    return best

random.seed(42)
trials = 0
for height in range(1, 9):
    for w in (4, 8):
        signer = MerkleSigner(height=height, w=w, token_bytes=counter_tokens())
        total = 1 << height
        messages_full = tuple(f"m{i}" for i in range(total))
        sigs_full = signer.sign_batch(messages_full)
        if total <= 8:
            subsets = [tuple(range(total))]
        else:
            subsets = []
        for k in (1, 2, 3, min(6, total)):
            if k > total: continue
            for _ in range(4):
                sub = tuple(sorted(random.sample(range(total), k)))
                if sub not in subsets:
                    subsets.append(sub)
        for sub in subsets:
            sigs = tuple(sigs_full[i] for i in sub)
            proof = multiproof_encode(signer.public_key, sigs)
            messages = tuple(messages_full[i] for i in sub)
            _, leaves, _ = _multiproof_parse(proof)
            one = multiproof_select(messages, proof, public_key=signer.public_key, indices=(leaves[0][0],))
            two = multiproof_select(messages, proof, public_key=signer.public_key,
                                    indices=tuple(leaves[i][0] for i in range(min(2,len(leaves)))))
            budgets = {len(proof), len(one), len(two), (len(proof)+len(one))//2, len(one)-1}
            for budget in budgets:
                if budget < 1: continue
                got = None
                try:
                    got = multiproof_partition(messages, proof, public_key=signer.public_key, max_bytes=budget)
                except ValueError:
                    pass
                b = brute_case(messages, proof, signer.public_key, leaves, budget)
                assert (got is not None) == (b is not None), (height, w, sub, budget, got is not None, b is not None)
                if got is None:
                    continue
                bkey = b[:3]
                got_key = (len(got), sum(map(len, got)), tuple(_multiproof_parse(p)[1][-1][0] for p in got))
                assert got_key == bkey, (got_key, bkey, height, w, sub, budget)
                bounds = b[3]
                expected = ()
